-- ACID: all or nothing, visible to others only after COMMIT
BEGIN;
UPDATE tickets SET sold = true
WHERE id = 7 AND sold = false;   -- only one of the concurrent buyers succeeds
INSERT INTO sales (ticket_id, customer_id) VALUES (7, 42);
COMMIT;

-- BASE: the write goes to node A; a read right after on node B
-- may still see the old value until replication catches up.

-- On the primary:
INSERT INTO orders (id, user_id, total) VALUES (42, 1, 99.90);

-- Right after, on the replica (asynchronous replication):
SELECT * FROM orders WHERE id = 42;   -- may return 0 rows

-- RIGHT: the confirmation page reads from the primary;
-- reports and listings can read from the replica.

CREATE VIEW active_users AS
SELECT id, name, email          -- no sensitive columns
FROM users
WHERE active = true;

SELECT name FROM active_users WHERE email LIKE '%@company.com';

GRANT SELECT ON active_users TO reporting;  -- access to the view only

-- Regular view: runs the GROUP BY on every query (not a cache)
CREATE VIEW sales_summary AS
SELECT product_id, SUM(quantity) AS sold
FROM order_items GROUP BY product_id;

-- Materialized view: stores the result; must be refreshed
CREATE MATERIALIZED VIEW sales_summary_mv AS
SELECT product_id, SUM(quantity) AS sold
FROM order_items GROUP BY product_id;

REFRESH MATERIALIZED VIEW sales_summary_mv;

// WRONG: holds a connection while waiting for the external API (seconds)
@Transactional
public void checkout(Order order) {
    orderRepository.save(order);
    paymentGateway.charge(order);        // slow HTTP call inside the transaction
}

// RIGHT: external call outside; the transaction only saves, and is short
public void checkout(Order order) {
    Charge charge = paymentGateway.charge(order);
    orderService.recordPayment(order, charge);  // @Transactional, in another bean
}

// MongoDB: the whole order in one document
db.orders.insertOne({
  _id: 123,
  customer: { id: 7, name: "Ana" },
  items: [
    { sku: "BOOK-01", qty: 2, price: NumberDecimal("49.90") },
    { sku: "PEN-02", qty: 1, price: NumberDecimal("5.00") }
  ],
  status: "PAID"
})

db.orders.find({ "customer.id": 7, status: "PAID" })

// WRONG: a "relational" model in MongoDB
db.orders.insertOne({ _id: 123, customerId: 7 })
db.items.insertOne({ orderId: 123, sku: "BOOK-01", qty: 2 })
// reading one order = querying orders + items + customers

// RIGHT: what is read together is stored together
db.orders.insertOne({
  _id: 123,
  customer: { id: 7, name: "Ana" },
  items: [ { sku: "BOOK-01", qty: 2 } ]
})

EXPLAIN ANALYZE
SELECT * FROM orders o
JOIN users u ON u.id = o.user_id
WHERE o.status = 'PAID' AND o.created_at > now() - interval '7 days';

-- Composite index: equality column first, then the range column
CREATE INDEX idx_orders_status_date ON orders (status, created_at);

-- Expression index for case-insensitive search
CREATE INDEX idx_users_email_lower ON users (lower(email));

-- WRONG: the rows are actually deleted
EXPLAIN ANALYZE DELETE FROM orders WHERE created_at < '2020-01-01';

-- RIGHT
BEGIN;
EXPLAIN ANALYZE DELETE FROM orders WHERE created_at < '2020-01-01';
ROLLBACK;

// Optimistic with JPA
@Entity
public class Product {
    @Id Long id;
    int stock;
    @Version Long version;   // UPDATE ... WHERE id = ? AND version = ?
}

// Pessimistic with Spring Data
public interface ProductRepository extends JpaRepository<Product, Long> {
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select p from Product p where p.id = :id")
    Optional<Product> findForUpdate(@Param("id") Long id);
}

// WRONG: the check never sees the stale screen
Product p = repository.findById(id).orElseThrow();   // version 7 now
p.setPrice(request.price());                         // the user edited version 5
repository.save(p);                                  // passes: the other admin's edit is lost

// RIGHT
if (!p.getVersion().equals(request.version())) {
    throw new ConflictException("The product changed — reload and try again");   // 409
}
